def subtract(a, b):
    # Filter out empty intervals and sort
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    if not b_intervals:
        return a_intervals

    # Merge overlapping/touching intervals in both a and b
    def merge_intervals(intervals):
        if not intervals:
            return []
        merged = [intervals[0]]
        for current in intervals[1:]:
            last = merged[-1]
            if current[0] <= last[1]:
                # Overlapping or touching, merge them
                merged[-1] = [last[0], max(last[1], current[1])]
            else:
                # Non-overlapping, add as new interval
                merged.append(current)
        return merged

    a_merged = merge_intervals(a_intervals)
    b_merged = merge_intervals(b_intervals)

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_intervals = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_intervals = []
            for curr_start, curr_end in current_intervals:
                if b_end <= curr_start or b_start >= curr_end:
                    # No overlap
                    new_intervals.append([curr_start, curr_end])
                else:
                    # There is overlap
                    if curr_start < b_start:
                        new_intervals.append([curr_start, b_start])
                    if b_end < curr_end:
                        new_intervals.append([b_end, curr_end])
            current_intervals = new_intervals

        result.extend(current_intervals)

    # Merge any touching intervals in result
    result = sorted(result)
    merged_result = []
    for interval in result:
        if merged_result and interval[0] <= merged_result[-1][1]:
            merged_result[-1][1] = max(merged_result[-1][1], interval[1])
        else:
            merged_result.append(interval)

    return merged_result

